let lang = localStorage.getItem('sah.lang') || (navigator.language || 'hi').slice(0, 2);
if (!D[lang]) lang = 'hi';

/* Secondary dictionaries (mr/bn/ta) are fetched only when they are actually used, so
   the boot path stays small on a weak link. When one lands the app re-translates —
   one screenful of English fallback is a fair price for a button that appears now. */
let extra = null;
let onReady = null;
